/**
 *  Represents a DCC (Digital Command Control) address for model trains.
 *  Valid DCC addresses range from 1 to 10239.
 */
export type DccAddress = number;

/**
 *  The NMRA and NEM Connectors for digital control (DCC)
 * 
 *  # Description
 *  The NMRA and NEM adopted standard mechanical and electrical interfaces to connect Multifunction
 *  Decoders to a locomotive's electrical system. These plugs and sockets make it simpler to install
 *  a decoder into a suitably equipped locomotive.
 * 
 *  In many cases a blanking plug must be removed before installing the decoder. If a locomotive
 *  is not DCC-Ready it will lack an interface and must use a Hardwired Decoder or a drop-in
 *  replacement DCC control board (if available) for that specific model.
 */
export type DccInterface = 
// 6 Pin standard mechanical and electrical interfaces (NMRA Small)
"NEM_651" | 
// 8 Pin standard mechanical and electrical interfaces (NMRA Medium)
"NEM_652" | 
// 4 Pin standard mechanical and electrical interfaces (NMRA Large)
"NEM_654" | 
// The PluX8 connector consists of two rows of 4 pins.
"PLUX_8" | "PLUX_12" | 
// The PluX16 connector consists of two rows of 8 pins.
"PLUX_16" | 
// The PluX22 connector consists of two rows of 11 pins.
"PLUX_22" | 
// standard connector for extremely tight applications, such as TT and N scale locomotives (NEM 662)
"NEXT_18" | "NEXT_18_S" | 
/**
 *  21MTC Connector interface is a standard adopted by both the NMRA and NEM (NEM 660).
 *  Its name comes from 21 pin Marklin/Trix Connector, developed by Marklin and ESU.
 */
"MTC_21";

/**
 *  A Decoder models a real-world model-railway decoder product.
 * 
 *  In the application domain a decoder is the canonical master record for a
 *  specific manufacturer product (for example an ESU LokPilot model). It
 *  captures the identity and capabilities of the physical module that can be
 *  installed into locomotives and other rolling stock.
 * 
 *  Important points for developers:
 *  - `Decoder` instances are stored centrally so many `OwnedRollingStock`
 *    records can reference the same decoder model via `installed_decoder_id`.
 *  - The `id` is a stable URN that identifies the product (example:
 *    `trn:decoder:esu:54621`). Use that URN when linking or displaying decoder
 *    information.
 * 
 *  Fields (plain language):
 *  - `id` — stable product identifier (URN) for the decoder model.
 *  - `manufacturer_id` — reference to the manufacturer entry.
 *  - `product_code` — human-facing product code or name from the manufacturer.
 *  - `decoder_type` — functional family (e.g. plain, sound).
 *  - `protocol` — digital protocol(s) the decoder supports (DCC, etc.).
 *  - `decoder_interface` — the physical DCC interface the decoder exposes.
 * 
 *  This struct is primarily used when recording which decoder model is
 *  installed into a piece of rolling stock and when presenting decoder details
 *  to the user (for example in an equipment detail view).
 */
export type Decoder = {
	// Unique identifier (URN) for this decoder.
	id: DecoderId,
	// Reference to the manufacturer (foreign key to `manufacturers.id`).
	manufacturerId: ManufacturerId,
	// Product code as provided by the manufacturer (human-readable).
	productCode: string,
	// The functional type of the decoder (plain, sound, etc.).
	decoderType: DecoderType,
	// The communication protocol implemented by this decoder.
	protocol: DigitalProtocol,
	// The physical DCC interface the decoder exposes (if any).
	decoderInterface: DccInterface,
};

/**
 *  Strongly-typed identifier for a decoder (master record).
 * 
 *  This newtype is `#[repr(transparent)]` and serializes as a plain string.
 *  URNs are of the form `trn:decoder:{manufacturer}:{product_code}`.
 */
export type DecoderId = string;

// Represents the type of a DCC decoder.
export type DecoderType = 
// Plain decoder without sound or function capabilities.
"PLAIN" | 
// Decoder with sound capabilities.
"SOUND" | 
// Decoder with function capabilities.
"FUNCTION" | 
// MultiProtocol decoder.
"MULTI_PROTOCOL";

// View representation of a decoder used within `DigitalRollingStockView`.
export type DecoderView = {
	// The unique identifier of the decoder
	id: DecoderId,
	// The manufacturer name of the decoder
	manufacturer: string,
	// The product code of the decoder
	product_code: string,
	// The type of the decoder
	decoder_type: DecoderType,
	// The digital protocol supported by the decoder
	protocol: DigitalProtocol,
	// The DCC interface type of the decoder
	decoder_interface: DccInterface,
};

