/**
 *  Model railway scales supported by the application.
 * 
 *  Each variant corresponds to a commonly used hobbyist scale name (for example
 *  `H0` or `00`). Use `Scale::ratio()` to obtain the numeric ratio that follows
 *  the `1:` notation (e.g. `Scale::H0` -> `1:87`). The `Display` implementation
 *  produces a human-friendly string such as `H0 (1:87)`.
 */
export type Scale = 
// H0 scale (1:87)
"H0" | 
// H0 narrow/metric (1:87)
"H0m" | 
// H0e (1:87)
"H0e" | 
// N scale (1:160)
"N" | 
// TT scale (1:120)
"TT" | 
// Z scale (1:220)
"Z" | 
// G scale (garden) (1:22.5)
"G" | 
// 1 scale (1:32)
"Scale1" | 
// 0 scale (1:43.5)
"Scale0" | 
// 00 (double-zero) scale (1:76.2)
"Scale00";

// Arguments for full-text search across railway model translations.
export type SearchRailwayModelsArgs = {
	// Search query. Minimum 2 characters.
	query: string,
};

/**
 *  Represents a seller (a shop, private seller or distributor) in the system.
 * 
 *  This domain-level struct is used by application use-cases and persisted via
 *  the sellers repository. Timestamps are represented using `chrono::DateTime<Utc>`.
 */
export type Seller = {
	// Strongly-typed seller identifier (format: `trn:seller:{slug}`).
	id: SellerId,
	// Human-readable seller name.
	name: string,
	// The category/type of the seller (Shop, Private, Marketplace, ...).
	sellerType: SellerType,
	// Optional contact email.
	email: string | null,
	// Optional contact phone number.
	phone: string | null,
	// Optional website URL (if available).
	websiteUrl: string | null,
	/**
	 *  Optional postal address structured as an `Address` domain value.
	 * 
	 *  When present this contains street, (extended) house number, city, region,
	 *  postal code and country as a single value object.
	 */
	address: Address | null,
	// Creation timestamp (UTC).
	createdAt: string,
	// Last update timestamp (UTC).
	updatedAt: string,
	/**
	 *  Events produced by operations on the aggregate that have not yet been
	 *  persisted/handled by a repository or unit of work.
	 */
	pendingEvents: SellerEvent[],
};

// Domain events produced by the `Seller` aggregate.
export type SellerEvent = ({ created: {
	aggregate_id: SellerId,
	name: string,
	seller_type: SellerType,
	email: string | null,
	phone: string | null,
	website_url: string | null,
	address: Address | null,
	created_at: string,
	updated_at: string,
} }) & { deleted?: never; updated?: never } | ({ updated: {
	aggregate_id: SellerId,
	name: string,
	seller_type: SellerType,
	email: string | null,
	phone: string | null,
	website_url: string | null,
	address: Address | null,
	created_at: string,
	updated_at: string,
} }) & { created?: never; deleted?: never } | ({ deleted: {
	aggregate_id: SellerId,
} }) & { created?: never; updated?: never };

// Strongly-typed identifier for a seller. Format: `trn:seller:{slug}`.
export type SellerId = string;

/**
 *  Represents the type/category of a seller.
 * 
 *  This enum is serialized/deserialized as screaming snake case (e.g. `SHOP`) and
 *  persisted to the database as text. It is used across the sellers feature to
 *  distinguish shops, private sellers, marketplaces and distributors.
 * 
 *  The type is intentionally strongly typed to avoid stringly-typed code and to
 *  provide a small surface for formatting and parsing (via `strum` and `sqlx`).
 */
export type SellerType = 
// A retail shop or online store selling products directly to customers.
"SHOP" | 
// A private (individual) seller — non-commercial person selling items.
"PRIVATE" | 
// An online marketplace aggregating multiple sellers.
"MARKETPLACE" | 
// A commercial distributor or wholesaler that supplies retailers.
"DISTRIBUTOR";

/**
 *  Presentation model for a `Seller` aggregate returned to the client.
 * 
 *  This view mirrors the persisted `Seller` fields but intentionally omits
 *  domain-only fields such as `pending_events`.
 */
export type SellerView = {
	// Unique identifier for the seller.
	id: SellerId,
	// Name of the seller.
	name: string,
	// Type of the seller.
	sellerType: SellerType,
	// Contact email of the seller.
	email: string | null,
	// Contact phone number of the seller.
	phone: string | null,
	// Website URL of the seller.
	websiteUrl: string | null,
	// Address of the seller.
	address: Address | null,
};

/**
 *  Represents the service class(es) for a rolling stock or service.
 * 
 *  | **Variant**                      | **Description**           |
 *  |:---------------------------------|:--------------------------|
 *  | `ServiceLevel::First`            | `1st class`               |
 *  | `ServiceLevel::Second`           | `2nd class`               |
 *  | `ServiceLevel::Third`            | `3rd class`               |
 *  | `ServiceLevel::FirstSecond`      | `Mixed 1st/2nd class`     |
 *  | `ServiceLevel::SecondThird`      | `Mixed 2nd/3rd class`     |
 *  | `ServiceLevel::FirstSecondThird` | `Mixed 1st/2nd/3rd class` |
 * 
 *  Parsing: `TryFrom<&str>` is implemented and accepts the string forms above
 *  (whitespace is trimmed). Formatting: `Display` is implemented and produces
 *  the corresponding string representation.
 */
export type ServiceLevel = "FIRST" | "SECOND" | "THIRD" | "FIRST_SECOND" | "SECOND_THIRD" | "FIRST_SECOND_THIRD";

